170// Game class to code the game logic
171class Game {
172private:
173
174    string word;
175    string user_answer;
176    string incorrect;
177    string entered_characters;
178    int misses;
179    Message message;
180
181public:
182
183    // constructor to initialize attributes
184    Game(string chosen_word) {
185        word = chosen_word;
186        incorrect = "";
187        entered_characters = "";
188        misses = 0;
189
190        for (int i = 0; i < word.length(); ++i) {
191            user_answer += "_";
192        }
193    }
194
195    // method to ensure that user input is
196    // an alphabet and not a previous input
197    bool is_guess_valid(char letter) {
198
199        if (!isalpha(letter)) {
200            message.invalid_character_message();
201            return false;
202        }
203
204        for (int i = 0; i < entered_characters.length(); ++i) {            
205            if (letter == entered_characters[i]) {
206                message.already_entered_message();
207                return false;
208            }
209        }
210
211        return true;
212    }
213
214    // method to check if guess is correct
215    void is_guess_correct(char letter) {
216
217        bool guess = false;
218
219        for (int i = 0; i < word.length(); i++) {
220            if (letter == word[i]) {
221                user_answer[i] = letter;
222                guess = true;
223            }
224        }
225
226        if (guess) {
227            message.correct_message();
228        }
229        else {
230            message.incorrect_message();
231            incorrect += letter;
232            incorrect += ", ";
233            ++misses;
234        }
235
236        entered_characters += letter;
237    }
238
239    // method to check if the game is over
240    bool is_game_over() {
241        if (user_answer == word || misses >= max_misses) {
242            return true;
243        }
244        return false;
245    }
246
247    // method to display the game status
248    void display_game_status() {
249        message.display_misses(misses);
250        message.display_incorrect_guesses(incorrect);
251        message.display_user_answer(user_answer);
252    }
253
254    // method to display the final result
255    void display_final_result() {
256        message.display_misses(misses);
257        message.final_result(user_answer, word);
258    }
259};
